head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > M > setPlaceholder]<br/>Textarea 컴포넌트의 placeholder 를 설정합니다.",
    "validation" : [
        "placeholder(필수) 파라미터로 입력창에 placeholder 로 표시될 텍스트를 문자열로 설정합니다.",
        "placeholder(필수) 파라미터가 null 이면 메소드가 실행되지 않습니다. (이전 placeholder 값 유지)",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (초기 placeholder 만 부여)
    let properties = {
        placeholder: "initial placeholder",
    };

    let cList = $c.gcm.createCList(properties);

    $c.gcm.createLabel('label="setPlaceholder 메소드 실행 후 placeholder 확인 (편집 영역 클릭 또는 [리턴값 확인] 버튼)"', '', 'label1');

    // textarea 생성 (placeholder 확인을 위해 입력값은 비움)
    await $c.gcm.createBasicTextArea(cList, 'ev:onclick="scwin.target1_onclick"');
    target1.setValue("");
}



scwin.target1_onclick = function (e) {
    // 실제 DOM 의 placeholder 속성 확인
    let dom = document.querySelector('textarea[id*="target1"]');
    let domPh = dom ? (dom.getAttribute("placeholder") || "") : "";

    // render.placeholder 확인
    let renderPh = (target1 && target1.render) ? (target1.render.placeholder || "") : "";

    wf_body_bottom.getObj("scwin").setReturnValue("DOM placeholder : '" + domPh + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("render.placeholder : '" + renderPh + "'");
}



scwin.btn_getReturn_onclick = function (e) {
    scwin.target1_onclick();
}



scwin.btn_setPlaceholder_onclick = function (e) {
    target1.setPlaceholder(par_placeholder.getValue());
};



scwin.btn_setPlaceholderNull_onclick = function (e) {
    // null 전달 시 메소드 미실행, 이전 placeholder 값 유지
    target1.setPlaceholder(null);
};
